    // Public API of the extensions defined in the glTF 2.1 3D Tiles vendor extensions (3d-tiles-2.0 branch).
    // The serialization code is generated by SharpGLTF.CodeGen.Extensions.Cesium, see Schema2/Generated.

    #region EXT_georeference and EXT_geospatial_crs

    /// <summary>
    /// EXT_georeference extension, attached to a <see cref="Node"/>.
    /// </summary>
    partial class ExtGeoreferenceNode
    {
        /// <summary>Longitude in degrees, in the range [-180, 180].</summary>
        public double Longitude
        {
            get => _longitude;
            set { Guard.MustBeBetweenOrEqualTo(value, _longitudeMinimum, _longitudeMaximum, nameof(value)); _longitude = value; }
        }

        /// <summary>Latitude in degrees, in the range [-90, 90].</summary>
        public double Latitude
        {
            get => _latitude;
            set { Guard.MustBeBetweenOrEqualTo(value, _latitudeMinimum, _latitudeMaximum, nameof(value)); _latitude = value; }
        }

        /// <summary>Height above (or below) the ellipsoid in meters.</summary>
        public double? Height { get => _height; set => _height = value; }
    }

    /// <summary>
    /// EXT_geospatial_crs extension, attached to a <see cref="ModelRoot"/>.
    /// The CRS definition is provided by a child extension like <see cref="ExtGeospatialCrsWkid"/> or <see cref="ExtGeospatialCrsWkt2"/>.
    /// </summary>
    partial class ExtGeospatialCrs
    {
        /// <summary>The CRS format, usually "wkid" or "wkt2".</summary>
        public string Format { get => _format; set => _format = value; }
    }

    /// <summary>
    /// EXT_geospatial_crs_wkid extension, attached to a <see cref="ExtGeospatialCrs"/>.
    /// </summary>
    partial class ExtGeospatialCrsWkid
    {
        public string Authority { get => _authority; set => _authority = value; }

        public int Wkid { get => _wkid; set => _wkid = value; }

        public int? VcsWkid { get => _vcsWkid; set => _vcsWkid = value; }

        /// <summary>Epoch for coordinates referenced to a dynamic CRS, expressed as a decimal year (e.g. "2019.81").</summary>
        public string Epoch { get => _epoch; set => _epoch = value; }
    }

    /// <summary>
    /// EXT_geospatial_crs_wkt2 extension, attached to a <see cref="ExtGeospatialCrs"/>.
