        public Vector3 Translation { get => _translation ?? _translationDefault; set => _translation = value == _translationDefault ? null : value; }

        /// <summary>The index of the shape in the top level glTF 2.1 "shapes" array.</summary>
        public int Shape { get => _shape; set => _shape = value; }
    }

