    #region EXT_voxels and 3DTILES_tileset_voxels

    /// <summary>
    /// Voxel padding.
    /// </summary>
    public partial class Tiles3DVoxelPadding
    {
        public Tiles3DVoxelPadding()
        {
            _before = new List<int>();
            _after = new List<int>();
        }

        public int[] Before { get => _before.Count == 0 ? null : _before.ToArray(); set { _CheckLength(value, _beforeMinItems, _beforeMaxItems); _before = value == null ? new List<int>() : new List<int>(value); } }

        public int[] After { get => _after.Count == 0 ? null : _after.ToArray(); set { _CheckLength(value, _afterMinItems, _afterMaxItems); _after = value == null ? new List<int>() : new List<int>(value); } }

        private static void _CheckLength(int[] value, int min, int max)
        {
            if (value == null) return;
            Guard.MustBeBetweenOrEqualTo(value.Length, min, max, nameof(value));
        }
    }

    /// <summary>
    /// EXT_voxels extension, attached to a <see cref="Node"/>.
    /// </summary>
    public partial class ExtVoxelsNode
    {
        public ExtVoxelsNode()
        {
            _attributes = new Dictionary<string, int>();
            _dimensions = new List<int>();
            _noData = new Dictionary<string, double[]>();
        }

        public int[] Dimensions
        {
            get => _dimensions.Count == 0 ? null : _dimensions.ToArray();
            set { if (value != null) Guard.MustBeBetweenOrEqualTo(value.Length, _dimensionsMinItems, _dimensionsMaxItems, nameof(value)); _dimensions = value == null ? new List<int>() : new List<int>(value); }
        }

        public Tiles3DVoxelPadding Padding { get => _padding; set => _padding = value; }

        /// <summary>Maps attribute names to accessor indices.</summary>
        public IDictionary<string, int> Attributes
        {
            get => _attributes;
            set => _attributes = value == null ? new Dictionary<string, int>() : new Dictionary<string, int>(value);
        }

        /// <summary>Maps attribute names to the values that represent missing data.</summary>
        public IDictionary<string, double[]> NoData
        {
            get => _noData;
            set => _noData = value == null ? new Dictionary<string, double[]>() : new Dictionary<string, double[]>(value);
        }
    }

