    {
        /// <summary>Index of the buffer view containing the availability bitstream.</summary>
        public int? Bitstream { get => _bitstream; set => _bitstream = value; }

        public int? AvailableCount
        {
            get => _availableCount;
            set { if (value.HasValue) Guard.MustBeGreaterThanOrEqualTo(value.Value, _availableCountMinimum, nameof(value)); _availableCount = value; }
        }

        /// <summary>Indicates whether all elements are available or all are unavailable.</summary>
        public Tiles3DAvailabilityConstant? Constant { get => _constant; set => _constant = value; }
    }

    /// <summary>
    /// 3DTILES_subtree extension, attached to a <see cref="ModelRoot"/>.
    /// </summary>
