        public Tiles3DSubtreeAvailability TileAvailability { get => _tileAvailability; set => _tileAvailability = value; }

        public Tiles3DSubtreeAvailability ContentAvailability { get => _contentAvailability; set => _contentAvailability = value; }

        public Tiles3DSubtreeAvailability ChildSubtreeAvailability { get => _childSubtreeAvailability; set => _childSubtreeAvailability = value; }

        /// <summary>Maps tile attribute semantics to accessor indices.</summary>
        public IDictionary<string, int> TileAttributes
        {
            get => _tileAttributes;
            set => _tileAttributes = value == null ? null : new Dictionary<string, int>(value);
        }

        /// <summary>Maps content attribute semantics to accessor indices.</summary>
