        {
            get => _contentAttributes;
            set => _contentAttributes = value == null ? null : new Dictionary<string, int>(value);
        }

        /// <summary>Index of the property table containing tile properties.</summary>
        public int? TileProperties { get => _tileProperties; set => _tileProperties = value; }

        /// <summary>Index of the property table containing content properties.</summary>
        public int? ContentProperties { get => _contentProperties; set => _contentProperties = value; }
    }

